/* ROM-only lookup. Unsupported size/name returnsNULL/empty, no substitute icon. */
const lv_font_t *Product_IconFont(uint32_t pixels){return pixels==24U?&font:NULL;}
const char *Product_IconText(ProductIcon id)
{
 switch(id){
 case PRODUCT_ICON_BUILD:return "\xEE\xA1\xA9";
 case PRODUCT_ICON_LOCAL_GAS_STATION:return "\xEE\x95\x86";
 default:return "";
 }
}

/* Keep all glyph metrics/cmaps internal; no runtime file callbacks. */
uint32_t Product_FooterIconsBind(void)
{
#if NOODOE_PRODUCT
    ResourceView v;
    if(!Resources_Get(RESOURCE_ICON_FOOTER,&v)||v.bytes!=404U)return 0;
    dsc.glyph_bitmap=v.data;
#endif
    return 1;
}
